#include <bits/stdc++.h>
using namespace std;

class Solution {public:int maximumWhiteTiles(vector<vector<int>>& tiles,int carpetLen){sort(tiles.begin(),tiles.end());int n=tiles.size();vector<long long> pre(n+1);for(int i=0;i<n;++i)pre[i+1]=pre[i]+tiles[i][1]-tiles[i][0]+1;int ans=0;for(int i=0;i<n;++i){long long end=1LL*tiles[i][0]+carpetLen-1;int j=upper_bound(tiles.begin(),tiles.end(),end,[](long long x,const vector<int>& t){return x<t[0];})-tiles.begin();long long covered=pre[j]-pre[i];if(j>i&&tiles[j-1][1]>end)covered-=tiles[j-1][1]-end;ans=max(ans,(int)covered);}return ans;} };
